REPLACE = {}

NEW_FILES = {'minicut/render/speed.py': '"""Media speed for sound: the part of a clip\'s sound that plays at a given time when the clip is faster or slower.\n\nTwo ways, chosen per clip (the "Pitch follows speed" switch):\n  * pitch follows speed: the sound is simply played faster / slower (like a tape): faster = higher, slower = deeper.\n    This is done on the fly, for any piece of the clip, with no waiting.\n  * pitch stays the same: the sound is stretched with WSOLA (overlap-add of pieces that are lined up with each other).\n    This is made for the whole clip in the background and kept in memory; until it is ready the preview uses the\n    first way, and the export waits for it, so the export always has the right sound.\nThe speed itself (constant or keyframed) comes from the clip: see src_time() in shared/core.py."""\nfrom ..shared.deps import *\nfrom ..shared.core import *\nimport threading\nfrom ..shared.tasks import TASKS\n\nSTRETCH_BUDGET = 1.0e9                 # bytes of stretched sound kept in memory\nSTRETCH_CACHE = OrderedDict()          # key -> int16 stereo array (clip time 0 ... clip length)\n_PENDING = set(); _LOCK = threading.Lock()\nSTRETCH_POOL = QThreadPool(); STRETCH_POOL.setMaxThreadCount(1)\n\n\ndef _snapshot(c):\n    """The few things of a clip that the mapping needs (copied, so editing the clip while it is computed is harmless)."""\n    sp = (c.get("props") or {}).get("speed") or {"v": 100.0, "k": []}\n    return {"kind": c["kind"], "inp": float(c["inp"]), "dur": float(c["dur"]), "props": {"speed": copy.deepcopy(sp)}}\n\n\ndef _key(c, data):\n    sp = c["props"]["speed"]\n    return (c.get("path"), id(data), round(float(c["inp"]), 4), round(float(c["dur"]), 4), json.dumps([sp["v"], sp["k"]], sort_keys=True))\n\n\ndef resample_piece(c, data, lt0, length, sr=SR):\n    """Pitch follows speed: the sound of local time lt0 ... lt0 + length, played faster / slower. float32, int16 scale."""\n    n = max(0, int(length * sr)); out = np.zeros((n, 2), np.float32)\n    if n == 0 or data is None or not len(data): return out\n    pos = src_time_arr(c, lt0 + np.arange(n) / sr) * sr\n    i0 = np.floor(pos).astype(np.int64); fr = (pos - i0).astype(np.float32)[:, None]\n    last = len(data) - 1; ok = (i0 >= 0) & (i0 <= last)\n    if not ok.any(): return out\n    lo = int(i0[ok].min()); hi = min(last, int(i0[ok].max()) + 1)\n    chunk = np.asarray(data[lo:hi + 1]).astype(np.float32)\n    a = np.clip(i0 - lo, 0, len(chunk) - 1); b = np.clip(i0 + 1 - lo, 0, len(chunk) - 1)\n    seg = chunk[a] * (1.0 - fr) + chunk[b] * fr\n    seg[~ok] = 0.0\n    return seg\n\n\ndef wsola(data, snap, sr=SR, alive=None):\n    """The whole clip\'s sound with its speed applied and the pitch kept. Returns int16 stereo, length = clip length."""\n    n_out = max(1, int(snap["dur"] * sr)); N = 2048; Hs = N // 2; tol = 512; D = 4\n    win = np.hanning(N).astype(np.float32)[:, None]\n    mono = (np.asarray(data[:, 0], np.float32) + np.asarray(data[:, 1], np.float32)) * 0.5\n    dec = mono[::D].copy(); L = len(data)\n    outs = np.arange(0, n_out, Hs); want = (src_time_arr(snap, outs / float(sr)) * sr).astype(np.int64)\n    out = np.zeros((n_out + N, 2), np.float32); wsum = np.zeros((n_out + N, 1), np.float32)\n    prev = None\n    for k, o in enumerate(outs):\n        if alive is not None and not alive(): return None\n        a = int(want[k]); pos = a\n        if prev is not None and 0 <= a < L:\n            nat = prev + Hs; lo = max(0, a - tol)\n            ref = dec[nat // D: nat // D + N // D]\n            cand = dec[lo // D: (a + tol + N) // D]\n            if len(ref) == N // D and len(cand) > len(ref):\n                c = np.correlate(cand, ref, "valid"); pos = lo + D * int(np.argmax(c))\n        prev = pos\n        if pos < 0 or pos >= L: continue\n        fr = np.asarray(data[pos:pos + N]).astype(np.float32); m = len(fr)\n        out[o:o + m] += fr * win[:m]; wsum[o:o + m] += win[:m]\n    y = out[:n_out] / np.maximum(wsum[:n_out], 1e-3)\n    return np.clip(y, -32768, 32767).astype(np.int16)\n\n\ndef _make(snap, data, key):\n    y = wsola(data, snap)\n    with _LOCK:\n        if y is not None:\n            STRETCH_CACHE[key] = y\n            while len(STRETCH_CACHE) > 1 and sum(v.nbytes for v in STRETCH_CACHE.values()) > STRETCH_BUDGET: STRETCH_CACHE.popitem(last=False)\n        _PENDING.discard(key)\n    return y\n\n\nclass _Job(QRunnable):\n    def __init__(self, snap, data, key, name):\n        super().__init__(); self.a = (snap, data, key); self.name = name; self.setAutoDelete(True)\n    def run(self):\n        task = TASKS.start("audio", "Speed  " + self.name)\n        try: _make(*self.a)\n        except Exception as ex:\n            print("speed:", ex)\n            with _LOCK: _PENDING.discard(self.a[2])\n        finally: task.finish()\n\n\ndef stretched(c, data, wait=False):\n    """Pitch-kept sound of the whole clip (clip time 0 ...), or None while it is being made."""\n    key = _key(c, data)\n    with _LOCK:\n        if key in STRETCH_CACHE: STRETCH_CACHE.move_to_end(key); return STRETCH_CACHE[key]\n    if wait: return _make(_snapshot(c), data, key)\n    with _LOCK:\n        if key not in _PENDING:\n            _PENDING.add(key); STRETCH_POOL.start(_Job(_snapshot(c), data, key, os.path.basename(c.get("path") or "")))\n    return None\n\n\ndef speed_piece(c, data, lt0, length, sr=SR, wait=False):\n    """Sound of local time lt0 ... lt0 + length of a clip that has a speed. float32 stereo, int16 scale."""\n    if not c.get("pitch_follow", False):\n        w = stretched(c, data, wait)\n        if w is not None:\n            n = max(0, int(length * sr)); s = max(0, int(lt0 * sr)); seg = w[s:s + n].astype(np.float32)\n            if len(seg) < n: seg = np.vstack([seg, np.zeros((n - len(seg), 2), np.float32)])\n            return seg\n    return resample_piece(c, data, lt0, length, sr)\n'}

HERE = os.path.dirname(os.path.abspath(__file__))
BACKUP_ROOT = os.path.join(HERE, "_patch_backup")
PATCH_NAME = "speed_filters_recordings_mediadelete"
try: sys.stdout.reconfigure(errors="replace")
except Exception: pass


def norm_hash(b): return hashlib.sha256(b.replace(b"\r\n", b"\n")).hexdigest()
def path_of(rel): return os.path.join(HERE, *rel.split("/"))
def read(rel):
    p = path_of(rel)
    return open(p, "rb").read() if os.path.exists(p) else None
def say(msg=""): print(msg, flush=True)


def edited_text(rel, raw):
    info = EDITS[rel]
    text = raw.decode("utf-8"); crlf = "\r\n" in text; t = text.replace("\r\n", "\n")
    for old, new in info["edits"]:
        n = t.count(old)
        if n != 1: raise ValueError("%s: expected the patch text exactly once, found %d times" % (rel, n))
        t = t.replace(old, new, 1)
    return (t.replace("\n", "\r\n") if crlf else t).encode("utf-8")


def plan():
    rows, outputs = [], {}
    for rel, info in list(EDITS.items()) + list(REPLACE.items()):
        cur = read(rel)
        if cur is None:
            rows.append((rel, "missing", "file not found")); continue
        if norm_hash(cur) == info["new"]:
            rows.append((rel, "same", "already up to date")); continue
        if norm_hash(cur) != info["base"]:
            rows.append((rel, "edited", "differs from the version this patch was made for")); continue
        try:
            outputs[rel] = edited_text(rel, cur) if rel in EDITS else info["content"].encode("utf-8")
            rows.append((rel, "ok", "will be updated"))
        except ValueError as ex:
            rows.append((rel, "edited", str(ex)))
    for rel, src in NEW_FILES.items():
        cur = read(rel)
        if cur is None: rows.append((rel, "new", "will be created")); outputs[rel] = src.encode("utf-8")
        elif cur.decode("utf-8", "replace") == src: rows.append((rel, "same", "already up to date"))
        else: rows.append((rel, "edited", "already exists and differs"))
    return rows, outputs


def import_ok():
    code = "import os; os.environ['QT_QPA_PLATFORM']='offscreen'; import minicut.app"
    try:
        r = subprocess.run([sys.executable, "-c", code], cwd=HERE, capture_output=True, text=True, timeout=180)
        return r.returncode == 0, (r.stderr or r.stdout)[-1500:]
    except Exception as ex: return False, str(ex)


def latest_backup():
    if not os.path.isdir(BACKUP_ROOT): return None
    ds = sorted(d for d in os.listdir(BACKUP_ROOT) if os.path.exists(os.path.join(BACKUP_ROOT, d, "MANIFEST.json")))
    return os.path.join(BACKUP_ROOT, ds[-1]) if ds else None


def revert(bdir):
    man = json.load(open(os.path.join(bdir, "MANIFEST.json"), encoding="utf-8"))
    for rel in man["replaced"]: shutil.copy2(os.path.join(bdir, *rel.split("/")), path_of(rel))
    for rel in man["created"]:
        if os.path.exists(path_of(rel)): os.remove(path_of(rel))
    say("Restored %d file(s), removed %d new file(s) from %s" % (len(man["replaced"]), len(man["created"]), bdir))


def main():
    if not os.path.isfile(path_of("minicut/app.py")):
        say("ERROR: minicut/app.py not found.\nPut this file in the MiniCut folder (next to file.py) and run again."); return 2
    if "--revert" in sys.argv:
        b = latest_backup()
        if not b: say("No backup found in _patch_backup/."); return 1
        revert(b); return 0
    rows, outputs = plan()
    say("MiniCut Patch 27: media speed, sound filters, recordings folder, delete media, no more freezes\n")
    for rel, st, note in rows: say("  %-44s %s" % (rel, note))
    say()
    if "--check" in sys.argv: return 0
    if all(st == "same" for _, st, _ in rows): say("Nothing to do: already installed."); return 0
    if any(st == "missing" for _, st, _ in rows):
        say("STOPPED. File missing:\n  " + "\n  ".join(rel for rel, st, _ in rows if st == "missing")); return 3
    bad = [rel for rel, st, _ in rows if st == "edited"]
    if bad and "--force" not in sys.argv:
        say("STOPPED. Files differ from expected:\n  " + "\n  ".join(bad) +
            "\nRun with --force to continue anyway (files are backed up first).")
        return 3
    if bad:
        for rel in bad:
            try:
                if rel in EDITS: outputs[rel] = edited_text(rel, read(rel))
                elif rel in REPLACE: outputs[rel] = REPLACE[rel]["content"].encode("utf-8")
            except ValueError as ex: say("STOPPED: %s" % ex); return 3
    base_ok, _ = import_ok()
    stamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S"); bdir = os.path.join(BACKUP_ROOT, stamp); replaced, created = [], []
    os.makedirs(bdir, exist_ok=True)
    for rel in outputs:
        cur = path_of(rel)
        if os.path.exists(cur):
            dst = os.path.join(bdir, *rel.split("/")); os.makedirs(os.path.dirname(dst), exist_ok=True); shutil.copy2(cur, dst); replaced.append(rel)
        else: created.append(rel)
    json.dump({"patch": PATCH_NAME, "created": created, "replaced": replaced},
              open(os.path.join(bdir, "MANIFEST.json"), "w", encoding="utf-8"), indent=1)
    try:
        for rel, data in outputs.items():
            p = path_of(rel); os.makedirs(os.path.dirname(p), exist_ok=True)
            with open(p, "wb") as f: f.write(data)
            if rel.endswith(".py"): py_compile.compile(p, doraise=True)
    except Exception as ex:
        say("ERROR writing files: %s\nRestoring backup ..." % ex); revert(bdir); return 1
    for rel, info in list(EDITS.items()) + list(REPLACE.items()):
        if norm_hash(read(rel)) != info["new"]:
            say("ERROR: %s hash mismatch after write, restoring backup." % rel); revert(bdir); return 1
    ok, err = import_ok()
    if base_ok and not ok:
        say("Import failed after update, restoring backup.\n" + err); revert(bdir); return 1
    for sub in ("minicut/render", "minicut/workspace", "minicut/shared"):
        shutil.rmtree(os.path.join(path_of(sub), "__pycache__"), ignore_errors=True)
    say("Done. %d file(s) updated, %d created.  Backup: %s" % (len(replaced), len(created), bdir))
    say("Start MiniCut as usual.")
    say("To undo:  python apply_27_speed_filters_recordings.py --revert")
    return 0


if __name__ == "__main__":
    code = 1
    try: code = main()
    except Exception as ex: say("Unexpected error: %r" % (ex,))
    if os.name == "nt" and "--no-pause" not in sys.argv: os.system("pause")
    sys.exit(code)
